-- ============================================================================
-- 0000_initial_schema.sql
-- DeepFlow (GB Electrical) — baseline schema for the `public` schema
-- ============================================================================
--
-- WHAT THIS FILE IS
--
-- This file is a from-scratch reconstruction of the ENTIRE current live
-- `public` schema of Supabase project `dzqyqpuhxdrrpipbehpk`, generated by
-- introspecting the live catalog directly (information_schema, pg_catalog,
-- pg_proc, pg_policies, pg_indexes, pg_publication_tables, pg_default_acl —
-- not approximated from docs, not reconstructed from memory) on 2026-08-11.
--
-- It exists to close a gap documented in full in
-- docs/architecture/07-sql-migrations.md §2 and §4, and
-- docs/planning/23-developer-onboarding.md §B2: every other file in this
-- `supabase/migrations/` folder is an ALTER TABLE / CREATE INDEX / CREATE
-- POLICY / CREATE OR REPLACE FUNCTION / DROP statement that assumes its
-- target already exists. None of them contain a CREATE TABLE. Replaying the
-- folder against a genuinely empty Supabase project fails immediately on the
-- first statement. This file is what those other files were always missing:
-- an actual bootstrap script.
--
-- HOW TO USE THIS FILE — READ THIS BEFORE APPLYING ANYTHING IN THIS FOLDER
--
--   * Standing up a brand-new, empty Supabase project at DeepFlow's CURRENT
--     schema state? Apply ONLY this file. It is self-sufficient — extensions,
--     sequences, tables, constraints, indexes, functions/RPCs, the one
--     trigger, RLS + every policy, default privileges, and the realtime
--     publication membership are all in here, already in their final,
--     current form.
--
--   * Do NOT then replay the other ~50 timestamped files in this folder
--     (20260718130728_... through 20260809010000_...) after this one. They
--     are this specific project's historical change log, not a second step
--     of a bootstrap sequence. Every change any of them ever made is already
--     reflected in this file in its final form. Replaying them after this
--     file would re-attempt already-applied ADD COLUMN / CREATE POLICY /
--     CREATE INDEX statements and fail with "already exists" errors (most
--     use IF NOT EXISTS / OR REPLACE / DROP...IF EXISTS guards so some would
--     silently no-op rather than error, but several — bare CREATE POLICY,
--     CREATE TABLE-less ALTER sequences — would not).
--
--   * Working against the existing live GB Electrical project
--     (`dzqyqpuhxdrrpipbehpk`)? You never need to apply this file at all —
--     the schema it describes already exists there. This file is for a
--     *second*, independent project only (see docs/planning/23-developer-
--     onboarding.md Part B — standing up a fresh instance for a new
--     company), or for disaster-recovery rebuild of this one.
--
--   * All future schema changes should still be written as new, individually
--     timestamped files in this folder per the existing convention
--     (docs/architecture/07-sql-migrations.md §5) — this file is a one-time
--     baseline capture, not a replacement for that convention.
--
-- WHAT THIS FILE DELIBERATELY DOES NOT COVER
--
--   * The `auth` schema itself (Supabase Auth's own tables) — provisioned by
--     Supabase automatically on every project, never DeepFlow's DDL. Two
--     things below DO reach into `auth`, both captured verbatim exactly as
--     they exist live: the `trg_auto_admin` trigger is defined ON
--     `auth.users`, and the `create_confirmed_user()` / `get_auth_users()`
--     functions read/write `auth.users`/`auth.identities` directly. Applying
--     this file requires a role with privileges on the `auth` schema (the
--     Supabase migration/CLI/MCP pathway already runs as such a role — see
--     docs/architecture/07-sql-migrations.md §5 for how migrations are
--     normally applied here).
--   * Storage: the app expects one bucket named `deepflow` (private, per
--     `20260808_make_deepflow_bucket_private.sql`) plus a set of
--     `storage.objects`/`storage.buckets` RLS policies — none of that is
--     `public`-schema DDL and none of it is captured here. See
--     docs/planning/23-developer-onboarding.md §B3 for what a fresh
--     instance needs on the Storage side.
--   * Edge Functions (`supabase/functions/*`) — deployed separately, not
--     part of this or any SQL migration.
--   * Any row data. This is schema only. The live project's data was fully
--     reset on 2026-08-06; every table is empty except `app_settings` (1
--     row) and `users` (1 row) — see docs/architecture/05-database.md §1.
--
-- ============================================================================


-- ============================================================================
-- SECTION 1 — EXTENSIONS
-- ============================================================================
-- Confirmed live via list_extensions: pgcrypto and uuid-ossp are installed
-- in the `extensions` schema, pg_stat_statements likewise. A genuinely fresh
-- Supabase project ships with `extensions` schema already present but these
-- specific extensions NOT yet enabled — IF NOT EXISTS makes this file safe
-- to apply either way.

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_stat_statements WITH SCHEMA extensions;


-- ============================================================================
-- SECTION 2 — SEQUENCES
-- ============================================================================
-- Six standalone sequences back the next_*_num()/portal_next_request_ref()
-- RPCs below (packages/business human-readable reference numbers: job
-- numbers, invoice numbers, credit-note numbers, agency numbers, proforma
-- numbers, portal client-request references). `invoice_audit.id` and
-- `push_subscriptions.id` are separate, identity-column-owned sequences —
-- those are declared inline on the table (GENERATED ALWAYS AS IDENTITY) in
-- Section 3, not here.
--
-- START WITH below matches each sequence's originally configured start
-- value (pg_sequences.start_value), not its current position — at the time
-- this file was generated, live `last_value`s had already advanced past
-- these (e.g. job_num_seq's last_value was 1063, inv_num_seq's was 2033)
-- because sequence position is data-like runtime state, not schema, and
-- wasn't part of the 2026-08-06 table-data reset. A fresh project starts
-- numbering from the same baseline GB Electrical's live project originally
-- did; it will not collide with production because it's a separate project.

CREATE SEQUENCE IF NOT EXISTS public.job_num_seq START WITH 1014 INCREMENT BY 1 MINVALUE 1 NO CYCLE;
CREATE SEQUENCE IF NOT EXISTS public.job_cr_seq START WITH 5 INCREMENT BY 1 MINVALUE 1 NO CYCLE;
CREATE SEQUENCE IF NOT EXISTS public.inv_num_seq START WITH 1998 INCREMENT BY 1 MINVALUE 1 NO CYCLE;
CREATE SEQUENCE IF NOT EXISTS public.agn_num_seq START WITH 2001 INCREMENT BY 1 MINVALUE 1 NO CYCLE;
CREATE SEQUENCE IF NOT EXISTS public.proforma_num_seq START WITH 1 INCREMENT BY 1 MINVALUE 1 NO CYCLE;
CREATE SEQUENCE IF NOT EXISTS public.portal_request_seq START WITH 2 INCREMENT BY 1 MINVALUE 1 NO CYCLE;


-- ============================================================================
-- SECTION 3 — TABLES
-- ============================================================================
-- Created in dependency order (referenced tables before referrers). Foreign
-- key constraints themselves are added afterward in Section 4, once every
-- table exists — this avoids forward-reference ordering problems entirely.
-- The one CHECK constraint that calls a function (invoices.items ->
-- valid_invoice_items()) is likewise added in Section 6, after that
-- function is created in Section 5, for the same reason.

-- ---------------------------------------------------------------------------
-- 3.1 persons — the Directory: landlords / individual clients
-- ---------------------------------------------------------------------------
CREATE TABLE public.persons (
  id                      text PRIMARY KEY,
  name                    text NOT NULL,
  phone                   text,
  email                   text,
  wa                      text,
  address                 text,
  notes                   text,
  roles                   jsonb DEFAULT '[]'::jsonb,
  rate                    numeric,
  created                 bigint,
  modified                bigint,
  portal_token            uuid DEFAULT gen_random_uuid(),
  portal_enabled          boolean DEFAULT false,
  last_portal_access      timestamptz,
  bankname                text,
  bankacc                 text,
  banksort                text,
  bankref                 text,
  agencyid                text,
  trade                   text,
  hourly_rate             numeric DEFAULT 0,
  default_trade           text,
  whatsapp                text,
  portal_pin_hash         text,
  portal_pin_fail_count   integer NOT NULL DEFAULT 0,
  portal_pin_locked_until timestamptz,
  archived                boolean NOT NULL DEFAULT false
);

-- ---------------------------------------------------------------------------
-- 3.2 agencies — the Directory: letting agencies
-- ---------------------------------------------------------------------------
CREATE TABLE public.agencies (
  id                      text PRIMARY KEY,
  name                    text NOT NULL,
  phone                   text,
  email                   text,
  wa                      text,
  address                 text,
  website                 text,
  notes                   text,
  portal_token            text UNIQUE DEFAULT encode(extensions.gen_random_bytes(12), 'hex'::text),
  created                 bigint,
  modified                bigint,
  portal_enabled          boolean DEFAULT false,
  last_portal_access      timestamptz,
  bankname                text,
  bankacc                 text,
  banksort                text,
  bankref                 text,
  portal_pin_hash         text,
  portal_pin_fail_count   integer NOT NULL DEFAULT 0,
  portal_pin_locked_until timestamptz
);

-- ---------------------------------------------------------------------------
-- 3.3 agents — the Directory: individual agents at an agency
-- ---------------------------------------------------------------------------
CREATE TABLE public.agents (
  id                      text PRIMARY KEY,
  name                    text NOT NULL,
  phone                   text,
  email                   text,
  wa                      text,
  title                   text,
  notes                   text,
  agencyid                text,
  created                 bigint,
  modified                bigint,
  portal_pin_hash         text,
  portal_pin_fail_count   integer NOT NULL DEFAULT 0,
  portal_pin_locked_until timestamptz
);

-- ---------------------------------------------------------------------------
-- 3.4 jobs — the central work-order record
-- ---------------------------------------------------------------------------
CREATE TABLE public.jobs (
  id                  text PRIMARY KEY,
  jobnum              text,
  date                text,
  address             text NOT NULL,
  referrer            text,
  trade               text,
  certtypes           jsonb DEFAULT '[]'::jsonb,
  engineer            text,
  description         text,
  timeslot            text,
  access              text,
  contact             text,
  price               numeric DEFAULT 0,
  notes               text,
  priority            text DEFAULT 'Normal'::text,
  status              text DEFAULT 'Pending'::text,
  landlordname        text,
  landlordphone       text,
  landlordemail       text,
  landlordaddr        text,
  landlordwa          text,
  landlordnotes       text,
  agencyname          text,
  agencyphone         text,
  agencyemail         text,
  agencynotes         text,
  agentname           text,
  agentphone          text,
  agentemail          text,
  portal_token        text UNIQUE DEFAULT encode(extensions.gen_random_bytes(12), 'hex'::text),
  created             bigint,
  modified            bigint,
  invnumber           text,
  linkedinvid         text,
  sortorder           integer,
  client_person_id    text,
  client_agency_id    text,
  checkin_time        timestamptz,
  checkout_time       timestamptz,
  checkin_location    text,
  engineer_signature  text,
  client_signature    text,
  invoice_id          uuid,
  agencyaddr          text,
  agencyaddress       text,
  confirmed           boolean DEFAULT true,
  postcode            text
);

-- ---------------------------------------------------------------------------
-- 3.5 certs — compliance certificates
-- ---------------------------------------------------------------------------
CREATE TABLE public.certs (
  id            text PRIMARY KEY,
  address       text,
  type          text,
  landlord      text,
  issuedate     text,
  expirydate    text,
  certnum       text,
  jobid         text,
  jobnum        text,
  engineer      text,
  notes         text,
  noexpiry      boolean DEFAULT false,
  created       bigint,
  pdf_url       text,
  pdf_path      text,
  agent         text,
  email         text,
  phone         text,
  notresponding boolean,
  appliances    jsonb DEFAULT '[]'::jsonb
);

-- ---------------------------------------------------------------------------
-- 3.6 invoices — every kind of billing document
-- ---------------------------------------------------------------------------
-- NOTE: the `valid_invoice_items(items)` CHECK constraint is added in
-- Section 6, after that function exists (Section 5) — see the file-level
-- note at the top of Section 3.
CREATE TABLE public.invoices (
  id                text PRIMARY KEY,
  number            text,
  clientid          text,
  clientname        text,
  clientemail       text,
  clientaddr        text,
  clientwa          text,
  date              text,
  duedate           text,
  description       text,
  jobid             text,
  items             jsonb DEFAULT '[]'::jsonb,
  status            text DEFAULT 'Draft'::text,
  created           bigint,
  agentcc           text,
  linkedjobid       text,
  jobref            text,
  terms             text,
  notes             text,
  client_person_id  text,
  client_agency_id  text,
  subtotal          numeric DEFAULT 0,
  vat_rate          numeric DEFAULT 20.00
                      CONSTRAINT invoices_vat_rate_sane_range
                      CHECK (vat_rate IS NULL OR (vat_rate >= 0::numeric AND vat_rate <= 100::numeric)),
  vat_amount        numeric DEFAULT 0,
  total             numeric DEFAULT 0,
  paid_amount       numeric DEFAULT 0,
  pdf_url           text,
  modified          timestamptz DEFAULT now(),
  isagency          boolean DEFAULT false,
  agencyaddress     text,
  landlordname      text,
  propertyaddress   text,
  jobnum            text,
  agentname         text,
  agentemail        text,
  agencyname        text,
  billtoname        text,
  billtoaddress     text,
  jobaddress        text,
  invoicetype       text DEFAULT 'landlord'::text,
  type              text,
  linkedinvid       text,
  reason            text,
  certtypes         text,
  jobdate           text,
  engineer          text,
  bill_to_override  boolean NOT NULL DEFAULT false,
  pdf_path          text
);

COMMENT ON COLUMN public.invoices.bill_to_override IS
  'When true, billtoname/billtoaddress on this invoice are a display-only override and must not be synced back to jobs.landlordname or the persons/agencies table.';

-- ---------------------------------------------------------------------------
-- 3.7 job_comments — internal, office-only notes thread on a job
-- ---------------------------------------------------------------------------
CREATE TABLE public.job_comments (
  id      text PRIMARY KEY,
  jobid   text,
  author  text,
  message text,
  ts      bigint DEFAULT (EXTRACT(epoch FROM now()) * (1000)::numeric)
);

-- ---------------------------------------------------------------------------
-- 3.8 attachments — index card for files held in Supabase Storage
-- ---------------------------------------------------------------------------
CREATE TABLE public.attachments (
  id                text PRIMARY KEY,
  jobid             text,
  name              text,
  type              text,
  mime              text,
  storage_path      text,
  url               text,
  uploaded_by_name  text,
  created           bigint DEFAULT (EXTRACT(epoch FROM now()) * (1000)::numeric),
  photo_slot        integer,
  photo_role        text
);

-- ---------------------------------------------------------------------------
-- 3.9 users — login accounts (office staff and field engineers share this)
-- ---------------------------------------------------------------------------
CREATE TABLE public.users (
  id                  text PRIMARY KEY,
  name                text NOT NULL,
  email               text,
  role                text DEFAULT 'engineer'::text,
  phone               text,
  active              boolean DEFAULT true,
  created             bigint DEFAULT (EXTRACT(epoch FROM now()) * (1000)::numeric),
  last_lat            double precision,
  last_lng            double precision,
  last_seen           bigint,
  last_accuracy       integer,
  auth_id             uuid,
  can_edit            boolean DEFAULT true,
  can_delete          boolean DEFAULT false,
  can_invoice         boolean DEFAULT true,
  can_finance         boolean DEFAULT false,
  see_landlord        boolean DEFAULT true,
  see_landlord_phone  boolean DEFAULT true,
  see_agent           boolean DEFAULT true,
  see_contact         boolean DEFAULT true,
  see_price           boolean DEFAULT false,
  internal_email      text,
  session_token       text,
  session_expires     bigint,
  is_protected        boolean DEFAULT false,
  pin_hash            text,
  pin_fail_count      integer NOT NULL DEFAULT 0,
  pin_locked_until    timestamptz,
  pin_reset_allowed   boolean NOT NULL DEFAULT false
);

-- ---------------------------------------------------------------------------
-- 3.10 activity — broad, one-way "what just happened" feed
-- ---------------------------------------------------------------------------
CREATE TABLE public.activity (
  id      text PRIMARY KEY,
  msg     text,
  type    text,
  ts      bigint DEFAULT (EXTRACT(epoch FROM now()) * (1000)::numeric),
  created timestamp without time zone DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- 3.11 engineer_requests — shared inbox: engineer overtime/leave + portal
--      "please book a job" client requests (told apart by `type`)
-- ---------------------------------------------------------------------------
CREATE TABLE public.engineer_requests (
  id            text PRIMARY KEY,
  engineer_name text NOT NULL,
  type          text NOT NULL,
  date          text,
  hours         numeric,
  rate          text,
  job           text,
  leave_type    text,
  leave_from    text,
  leave_to      text,
  notes         text,
  status        text DEFAULT 'pending'::text,
  office_reply  text,
  created       bigint DEFAULT (EXTRACT(epoch FROM now()) * (1000)::numeric)
);

-- ---------------------------------------------------------------------------
-- 3.12 engineer_alerts — office-to-engineer broadcast messages
-- ---------------------------------------------------------------------------
CREATE TABLE public.engineer_alerts (
  id      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  target  text DEFAULT 'all'::text,
  type    text DEFAULT 'info'::text,
  title   text,
  message text,
  sent_by text,
  created bigint,
  expires bigint,
  status  text DEFAULT 'active'::text
);

-- ---------------------------------------------------------------------------
-- 3.13 app_settings — single-row (key='__all__') JSON configuration store
-- ---------------------------------------------------------------------------
CREATE TABLE public.app_settings (
  key     text PRIMARY KEY,
  value   text NOT NULL,
  updated bigint DEFAULT 0
);

-- ---------------------------------------------------------------------------
-- 3.14 payments — one row per payment recorded against an invoice
-- ---------------------------------------------------------------------------
CREATE TABLE public.payments (
  id            text PRIMARY KEY,
  inv_id        text NOT NULL,
  date          text,
  amount        numeric NOT NULL DEFAULT 0,
  method        text DEFAULT 'Bank Transfer'::text,
  ref           text,
  recorded_by   text,
  created       bigint,
  notes         text
);

-- ---------------------------------------------------------------------------
-- 3.15 cert_reminder_log — dedup log: one row per expiry reminder sent
-- ---------------------------------------------------------------------------
CREATE TABLE public.cert_reminder_log (
  id          text PRIMARY KEY DEFAULT (gen_random_uuid())::text,
  cert_id     text NOT NULL,
  sent_at     timestamptz NOT NULL DEFAULT now(),
  days_before integer,
  method      text DEFAULT 'whatsapp'::text
);

-- ---------------------------------------------------------------------------
-- 3.16 expenses — engineer-facing cost tracking
-- ---------------------------------------------------------------------------
CREATE TABLE public.expenses (
  id          text PRIMARY KEY,
  date        text,
  engineer    text,
  category    text,
  description text,
  cost        numeric DEFAULT 0,
  receipt     text,
  created     bigint,
  jobref      text,
  modified    bigint
);

-- ---------------------------------------------------------------------------
-- 3.17 overtime — engineer overtime/absence hours (payroll deductions use
--      deliberately negative `hours`)
-- ---------------------------------------------------------------------------
CREATE TABLE public.overtime (
  id       text PRIMARY KEY,
  engineer text,
  date     text,
  type     text,
  hours    numeric DEFAULT 0,
  label    text,
  notes    text,
  created  bigint
);

-- ---------------------------------------------------------------------------
-- 3.18 audit_log — strict, narrow, Admin-only sensitive-event trail
-- ---------------------------------------------------------------------------
CREATE TABLE public.audit_log (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  type        text,
  staff_name  text,
  staff_email text,
  staff_role  text,
  details     jsonb,
  created_at  timestamptz DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- 3.19 portal_contacts — manually-curated "who to contact" list shown in
--      the Client Portal
-- ---------------------------------------------------------------------------
CREATE TABLE public.portal_contacts (
  id           text PRIMARY KEY,
  label        text,
  contact_name text,
  phone        text,
  sort_order   integer DEFAULT 0,
  created      timestamptz DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- 3.20 invoice_audit — per-invoice audit trail (created/sent/failed/
--      converted events). Column names quoted where they are camelCase or
--      reserved words ("invoiceId", "from", "to", "user"), matching live.
-- ---------------------------------------------------------------------------
CREATE TABLE public.invoice_audit (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  "invoiceId" text NOT NULL,
  action      text,
  details     text,
  "from"      text,
  "to"        text,
  "user"      text,
  timestamp   bigint
);

-- ---------------------------------------------------------------------------
-- 3.21 push_subscriptions — Web Push subscription storage (staff + portal
--      client subscriptions; entity_table/entity_id identify the owner)
-- ---------------------------------------------------------------------------
CREATE TABLE public.push_subscriptions (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entity_table  text NOT NULL,
  entity_id     text NOT NULL,
  endpoint      text NOT NULL UNIQUE,
  p256dh        text NOT NULL,
  auth          text NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);


-- ============================================================================
-- SECTION 4 — FOREIGN KEYS
-- ============================================================================
-- Exactly nine, all confirmed live via information_schema.referential_
-- constraints. Five are original/long-standing (agents/attachments/certs/
-- invoices/job_comments -> jobs or agencies); four are the newest addition,
-- from 20260809010000_fix_client_id_type_mismatch_add_real_fks.sql, which
-- changed jobs/invoices.client_person_id/client_agency_id from a type-
-- mismatched uuid (that could never really be a FK against persons.id/
-- agencies.id, both `text`) to `text`, then added the real constraints below.
-- ON DELETE SET NULL (not RESTRICT/CASCADE) on every Directory-pointing FK
-- is deliberate: removing a person/agency/job should never be blocked by,
-- or cascade-delete, linked history.

ALTER TABLE public.agents
  ADD CONSTRAINT agents_agencyid_fkey FOREIGN KEY (agencyid) REFERENCES public.agencies(id) ON DELETE SET NULL;

ALTER TABLE public.attachments
  ADD CONSTRAINT attachments_jobid_fkey FOREIGN KEY (jobid) REFERENCES public.jobs(id) ON DELETE CASCADE;

ALTER TABLE public.certs
  ADD CONSTRAINT certs_jobid_fkey FOREIGN KEY (jobid) REFERENCES public.jobs(id) ON DELETE SET NULL;

ALTER TABLE public.invoices
  ADD CONSTRAINT invoices_jobid_fkey FOREIGN KEY (jobid) REFERENCES public.jobs(id) ON DELETE SET NULL;

ALTER TABLE public.job_comments
  ADD CONSTRAINT job_comments_jobid_fkey FOREIGN KEY (jobid) REFERENCES public.jobs(id) ON DELETE CASCADE;

ALTER TABLE public.jobs
  ADD CONSTRAINT jobs_client_person_id_fkey FOREIGN KEY (client_person_id) REFERENCES public.persons(id) ON DELETE SET NULL;

ALTER TABLE public.jobs
  ADD CONSTRAINT jobs_client_agency_id_fkey FOREIGN KEY (client_agency_id) REFERENCES public.agencies(id) ON DELETE SET NULL;

ALTER TABLE public.invoices
  ADD CONSTRAINT invoices_client_person_id_fkey FOREIGN KEY (client_person_id) REFERENCES public.persons(id) ON DELETE SET NULL;

ALTER TABLE public.invoices
  ADD CONSTRAINT invoices_client_agency_id_fkey FOREIGN KEY (client_agency_id) REFERENCES public.agencies(id) ON DELETE SET NULL;


-- ============================================================================
-- SECTION 5 — INDEXES
-- ============================================================================
-- Only indexes NOT already implied by a PRIMARY KEY/UNIQUE constraint
-- declared in Section 3. Every definition below is transcribed verbatim
-- from live `pg_indexes.indexdef`.

CREATE INDEX idx_agents_agencyid ON public.agents USING btree (agencyid);

CREATE INDEX idx_attachments_jobid ON public.attachments USING btree (jobid);

CREATE INDEX idx_certs_expiry ON public.certs USING btree (expirydate);
CREATE INDEX idx_certs_jobid ON public.certs USING btree (jobid);

CREATE INDEX idx_invoices_jobid ON public.invoices USING btree (jobid);

CREATE INDEX idx_job_comments_jobid ON public.job_comments USING btree (jobid);

CREATE INDEX idx_jobs_client_agency ON public.jobs USING btree (client_agency_id);
CREATE INDEX idx_jobs_client_person ON public.jobs USING btree (client_person_id);
CREATE INDEX idx_jobs_date ON public.jobs USING btree (date);
CREATE INDEX idx_jobs_engineer ON public.jobs USING btree (engineer);
CREATE INDEX idx_jobs_invoice ON public.jobs USING btree (invoice_id);
CREATE INDEX idx_jobs_portal ON public.jobs USING btree (portal_token);
CREATE INDEX idx_jobs_status ON public.jobs USING btree (status);
CREATE INDEX jobs_postcode_idx ON public.jobs USING btree (postcode);

-- Unique (not a named table constraint — index-only uniqueness, matches live)
CREATE UNIQUE INDEX idx_persons_portal_token ON public.persons USING btree (portal_token);

CREATE INDEX push_subscriptions_entity_idx ON public.push_subscriptions USING btree (entity_table, entity_id);

CREATE INDEX idx_users_auth_id ON public.users USING btree (auth_id);
CREATE INDEX idx_users_email ON public.users USING btree (email);
CREATE INDEX idx_users_role ON public.users USING btree (role);
CREATE INDEX idx_users_session_token ON public.users USING btree (session_token);
-- Partial unique index: only enforces uniqueness where phone is actually set
CREATE UNIQUE INDEX users_phone_unique ON public.users USING btree (phone) WHERE (phone IS NOT NULL);

CREATE INDEX invoice_audit_invoiceid_idx ON public.invoice_audit USING btree ("invoiceId");


-- ============================================================================
-- SECTION 6 — FUNCTIONS / RPCs
-- ============================================================================
-- All 41 functions in the `public` schema, transcribed verbatim via
-- pg_get_functiondef(oid) — bodies, SET search_path, SECURITY DEFINER/
-- volatility markers, and default arguments are exactly what's live, not
-- reconstructed. Grouped alphabetically (the order they were fetched in),
-- which is safe: no SQL-language function here calls another public
-- function (only tables/sequences/auth.uid(), all already created above),
-- and plpgsql function bodies aren't validated against referenced-object
-- existence at CREATE time, only at call time — so there is no forward-
-- reference ordering hazard among these 41 regardless of the order below.
--
-- One function is knowingly captured "broken", on purpose: verify_engineer_
-- login() (near the end of this section) references `v_user.pin`, a column
-- that no longer exists on `users` (superseded by pin_hash/pin_fail_count/
-- pin_locked_until/pin_reset_allowed). It would raise "column pin does not
-- exist" if actually invoked. It is captured byte-for-byte anyway because
-- that is what is genuinely live — its EXECUTE grant was already revoked
-- from anon/authenticated by 20260725163831_h1_revoke_dead_verify_engineer_
-- login_rpc.sql, so it is unreachable via the API today; see Section 8.

CREATE OR REPLACE FUNCTION public.admin_set_seq(seq_name text, new_start integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF seq_name NOT IN ('job_num_seq','job_cr_seq','inv_num_seq','agn_num_seq','proforma_num_seq') THEN
    RAISE EXCEPTION 'Invalid sequence name: %', seq_name;
  END IF;
  EXECUTE format('ALTER SEQUENCE %I RESTART WITH %s', seq_name, GREATEST(new_start, 1));
END;
$function$;

