CREATE OR REPLACE FUNCTION public.check_cert_reminder_setup()
 RETURNS TABLE(step text, done boolean, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Step 2: table
  RETURN QUERY SELECT 'table'::text,
    EXISTS(SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='cert_reminder_log'),
    'cert_reminder_log table'::text;

  -- Step 3: function
  RETURN QUERY SELECT 'function'::text,
    EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON p.pronamespace=n.oid
           WHERE n.nspname='public' AND p.proname='send_cert_reminders'),
    'send_cert_reminders() function'::text;

  -- Step 4: cron schedule — requires the pg_cron extension itself to be
  -- enabled (Database → Extensions in the dashboard, can't be done from
  -- SQL alone). If it isn't enabled yet, cron.job doesn't exist at all —
  -- catch that specific case and report it plainly instead of erroring.
  BEGIN
    RETURN QUERY SELECT 'cron'::text,
      EXISTS(SELECT 1 FROM cron.job WHERE jobname='deepflow-cert-reminders'),
      'daily 9am schedule'::text;
  EXCEPTION WHEN undefined_table OR insufficient_privilege THEN
    RETURN QUERY SELECT 'cron'::text, false,
      'pg_cron extension not enabled yet (Database → Extensions)'::text;
  END;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_confirmed_user(p_email text, p_password text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'auth', 'public'
AS $function$
DECLARE v_user_id uuid; v_encrypted_pw text;
BEGIN
  v_user_id := gen_random_uuid();
  v_encrypted_pw := crypt(p_password, gen_salt('bf'));
  INSERT INTO auth.users (instance_id,id,aud,role,email,encrypted_password,
    email_confirmed_at,recovery_sent_at,last_sign_in_at,raw_app_meta_data,
    raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,
    email_change_token_new,recovery_token)
  VALUES ('00000000-0000-0000-0000-000000000000',v_user_id,'authenticated',
    'authenticated',p_email,v_encrypted_pw,now(),now(),now(),
    '{"provider":"email","providers":["email"]}','{}',now(),now(),'','','','');
  INSERT INTO auth.identities (id,user_id,provider_id,identity_data,provider,
    last_sign_in_at,created_at,updated_at)
  VALUES (gen_random_uuid(),v_user_id,p_email,
    json_build_object('sub',v_user_id::text,'email',p_email),'email',now(),now(),now());
  RETURN v_user_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.engineer_allow_pin_reset(p_id text, p_allow boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT is_office() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  UPDATE users SET pin_reset_allowed = p_allow
  WHERE id = p_id AND role = 'engineer';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Engineer not found';
  END IF;
  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION public.engineer_pin_clear(p_id text, p_allow_reset boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT is_office() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  UPDATE users SET pin_hash = NULL, session_token = NULL, session_expires = NULL,
    pin_fail_count = 0, pin_locked_until = NULL, pin_reset_allowed = p_allow_reset
  WHERE id = p_id AND role = 'engineer';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Engineer not found';
  END IF;
  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION public.engineer_pin_login(p_phone text, p_pin text)
 RETURNS TABLE(ok boolean, session_token text, session_expires bigint, eng_id text, eng_name text, error_msg text, needs_setup boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  rec record;
  new_token text;
  new_expires bigint;
  fails int;
BEGIN
  SELECT * INTO rec FROM users
  WHERE phone = p_phone AND role = 'engineer' AND active = true;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::text, NULL::bigint, NULL::text, NULL::text, 'Invalid phone or PIN'::text, false;
    RETURN;
  END IF;

  IF rec.pin_hash IS NULL THEN
    IF rec.pin_reset_allowed THEN
      RETURN QUERY SELECT false, NULL::text, NULL::bigint, rec.id, rec.name, 'Set up your PIN to continue'::text, true;
    ELSE
      RETURN QUERY SELECT false, NULL::text, NULL::bigint, NULL::text, NULL::text, 'Not authorised to log in — ask your office to grant you access'::text, false;
    END IF;
    RETURN;
  END IF;

  IF rec.pin_locked_until IS NOT NULL AND rec.pin_locked_until > now() THEN
    RETURN QUERY SELECT false, NULL::text, NULL::bigint, NULL::text, NULL::text, 'Too many attempts — try again later'::text, false;
    RETURN;
  END IF;

  IF p_pin !~ '^[0-9]{6}$' THEN
    RETURN QUERY SELECT false, NULL::text, NULL::bigint, NULL::text, NULL::text, 'Invalid phone or PIN'::text, false;
    RETURN;
  END IF;

  IF crypt(p_pin, rec.pin_hash) <> rec.pin_hash THEN
    fails := COALESCE(rec.pin_fail_count,0) + 1;
    IF fails >= 5 THEN
      UPDATE users SET pin_fail_count = fails, pin_locked_until = now() + interval '15 minutes' WHERE users.id = rec.id;
    ELSE
      UPDATE users SET pin_fail_count = fails WHERE users.id = rec.id;
    END IF;
    RETURN QUERY SELECT false, NULL::text, NULL::bigint, NULL::text, NULL::text, 'Invalid phone or PIN'::text, false;
    RETURN;
  END IF;

  new_token := encode(gen_random_bytes(32), 'hex');
  new_expires := extract(epoch FROM now())::bigint + 90*24*60*60;

  UPDATE users SET session_token = new_token, session_expires = new_expires,
    pin_fail_count = 0, pin_locked_until = NULL, last_seen = extract(epoch from now())::bigint
  WHERE users.id = rec.id;

  RETURN QUERY SELECT true, new_token, new_expires, rec.id, rec.name, NULL::text, false;
END;
$function$;

CREATE OR REPLACE FUNCTION public.engineer_pin_self_setup(p_phone text, p_new_pin text)
 RETURNS TABLE(ok boolean, session_token text, session_expires bigint, eng_id text, eng_name text, error_msg text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  rec record;
  new_token text;
  new_expires bigint;
BEGIN
  IF p_new_pin !~ '^[0-9]{6}$' THEN
    RETURN QUERY SELECT false, NULL::text, NULL::bigint, NULL::text, NULL::text, 'PIN must be exactly 6 digits'::text;
    RETURN;
  END IF;

  SELECT * INTO rec FROM users
  WHERE phone = p_phone AND role = 'engineer' AND active = true;

  IF NOT FOUND OR rec.pin_hash IS NOT NULL OR NOT rec.pin_reset_allowed THEN
    RETURN QUERY SELECT false, NULL::text, NULL::bigint, NULL::text, NULL::text, 'Not authorised to set a PIN right now'::text;
    RETURN;
  END IF;

  new_token := encode(gen_random_bytes(32), 'hex');
  new_expires := extract(epoch FROM now())::bigint + 90*24*60*60;

  UPDATE users SET pin_hash = crypt(p_new_pin, gen_salt('bf')), pin_reset_allowed = false,
    session_token = new_token, session_expires = new_expires,
    pin_fail_count = 0, pin_locked_until = NULL, last_seen = extract(epoch from now())::bigint
  WHERE users.id = rec.id;

  RETURN QUERY SELECT true, new_token, new_expires, rec.id, rec.name, NULL::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.engineer_pin_set(p_id text, p_pin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NOT is_office() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  IF p_pin !~ '^[0-9]{6}$' THEN
    RAISE EXCEPTION 'PIN must be exactly 6 digits';
  END IF;
  UPDATE users SET pin_hash = crypt(p_pin, gen_salt('bf')), pin_fail_count = 0, pin_locked_until = NULL,
    session_token = NULL, session_expires = NULL
  WHERE id = p_id AND role = 'engineer';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Engineer not found';
  END IF;
  RETURN true;
END;
$function$;

