CREATE OR REPLACE FUNCTION public.is_valid_engineer_token()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_token text; v_count int;
BEGIN
  BEGIN
    v_token := current_setting('request.headers', true)::json->>'x-engineer-token';
  EXCEPTION WHEN OTHERS THEN RETURN false; END;
  IF v_token IS NULL OR v_token = '' THEN RETURN false; END IF;
  SELECT count(*) INTO v_count FROM users
  WHERE session_token = v_token
    AND role = 'engineer'
    AND active = true
    AND session_expires > extract(epoch from now())::bigint;
  RETURN v_count > 0;
END;
$function$;

