CREATE OR REPLACE FUNCTION public.portal_get_invoices(p_type text, p_id text)
 RETURNS SETOF invoices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_name text; v_email text;
BEGIN
  IF p_type = 'landlord' THEN
    SELECT name INTO v_name FROM persons WHERE id::text = p_id;
    RETURN QUERY SELECT * FROM invoices
      WHERE client_person_id::text = p_id
         OR (v_name IS NOT NULL AND (lower(clientname) = lower(v_name) OR lower(landlordname) = lower(v_name) OR lower(billtoname) = lower(v_name)))
      ORDER BY created DESC;
  ELSIF p_type = 'agency' THEN
    SELECT name INTO v_name FROM agencies WHERE id::text = p_id;
    RETURN QUERY SELECT * FROM invoices
      WHERE client_agency_id::text = p_id
         OR (v_name IS NOT NULL AND (lower(clientname) = lower(v_name) OR lower(agencyname) = lower(v_name) OR lower(billtoname) = lower(v_name)))
      ORDER BY created DESC;
  ELSIF p_type = 'agent' THEN
    SELECT name, email INTO v_name, v_email FROM agents WHERE id::text = p_id;
    IF v_name IS NOT NULL THEN
      RETURN QUERY SELECT * FROM invoices
        WHERE lower(agentname) = lower(v_name) OR (v_email IS NOT NULL AND lower(agentemail) = lower(v_email)) OR lower(billtoname) = lower(v_name)
        ORDER BY created DESC;
    END IF;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.portal_get_jobs(p_type text, p_id text)
 RETURNS SETOF jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_name text; v_email text;
BEGIN
  IF p_type = 'landlord' THEN
    SELECT name INTO v_name FROM persons WHERE id::text = p_id;
    RETURN QUERY SELECT * FROM jobs
      WHERE client_person_id::text = p_id
         OR (v_name IS NOT NULL AND lower(landlordname) = lower(v_name))
      ORDER BY date DESC;
  ELSIF p_type = 'agency' THEN
    SELECT name INTO v_name FROM agencies WHERE id::text = p_id;
    RETURN QUERY SELECT * FROM jobs
      WHERE client_agency_id::text = p_id
         OR (v_name IS NOT NULL AND lower(agencyname) = lower(v_name))
      ORDER BY date DESC;
  ELSIF p_type = 'agent' THEN
    SELECT name, email INTO v_name, v_email FROM agents WHERE id::text = p_id;
    IF v_name IS NOT NULL THEN
      RETURN QUERY SELECT * FROM jobs
        WHERE lower(agentname) = lower(v_name) OR (v_email IS NOT NULL AND lower(agentemail) = lower(v_email))
        ORDER BY date DESC;
    END IF;
  END IF;
END;
$function$;

