CREATE OR REPLACE FUNCTION public.portal_pin_reset(p_table text, p_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_table NOT IN ('persons','agencies','agents') THEN
    RAISE EXCEPTION 'Invalid table: %', p_table;
  END IF;
  EXECUTE format('UPDATE %I SET portal_pin_hash = NULL, portal_pin_fail_count = 0, portal_pin_locked_until = NULL WHERE id = $1', p_table) USING p_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.portal_pin_set(p_table text, p_id text, p_pin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE existing text;
BEGIN
  IF p_table NOT IN ('persons','agencies','agents') THEN
    RAISE EXCEPTION 'Invalid table: %', p_table;
  END IF;
  IF p_pin !~ '^[0-9]{6}$' THEN
    RAISE EXCEPTION 'PIN must be exactly 6 digits';
  END IF;
  EXECUTE format('SELECT portal_pin_hash FROM %I WHERE id = $1', p_table) INTO existing USING p_id;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'A PIN is already set for this account';
  END IF;
  EXECUTE format(
    'UPDATE %I SET portal_pin_hash = crypt($1, gen_salt(''bf'')), portal_pin_fail_count = 0, portal_pin_locked_until = NULL WHERE id = $2',
    p_table
  ) USING p_pin, p_id;
  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION public.portal_pin_status(p_table text, p_id text)
 RETURNS TABLE(has_pin boolean, locked_until timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_table NOT IN ('persons','agencies','agents') THEN
    RAISE EXCEPTION 'Invalid table: %', p_table;
  END IF;
  RETURN QUERY EXECUTE format(
    'SELECT portal_pin_hash IS NOT NULL, portal_pin_locked_until FROM %I WHERE id = $1', p_table
  ) USING p_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.portal_pin_verify(p_table text, p_id text, p_pin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE stored text; fails int; lockedUntil timestamptz; ok boolean;
BEGIN
  IF p_table NOT IN ('persons','agencies','agents') THEN
    RAISE EXCEPTION 'Invalid table: %', p_table;
  END IF;
  EXECUTE format('SELECT portal_pin_hash, portal_pin_fail_count, portal_pin_locked_until FROM %I WHERE id = $1', p_table)
    INTO stored, fails, lockedUntil USING p_id;

  IF stored IS NULL THEN RETURN false; END IF;
  IF lockedUntil IS NOT NULL AND lockedUntil > now() THEN RETURN false; END IF;

  ok := (crypt(p_pin, stored) = stored);

  IF ok THEN
    EXECUTE format('UPDATE %I SET portal_pin_fail_count = 0, portal_pin_locked_until = NULL WHERE id = $1', p_table) USING p_id;
  ELSE
    fails := COALESCE(fails,0) + 1;
    IF fails >= 5 THEN
      EXECUTE format('UPDATE %I SET portal_pin_fail_count = $1, portal_pin_locked_until = now() + interval ''15 minutes'' WHERE id = $2', p_table) USING fails, p_id;
    ELSE
      EXECUTE format('UPDATE %I SET portal_pin_fail_count = $1 WHERE id = $2', p_table) USING fails, p_id;
    END IF;
  END IF;

  RETURN ok;
END;
$function$;

CREATE OR REPLACE FUNCTION public.portal_push_subscribe(p_table text, p_id text, p_endpoint text, p_p256dh text, p_auth text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_table NOT IN ('persons','agencies','agents') THEN
    RAISE EXCEPTION 'Invalid table: %', p_table;
  END IF;
  INSERT INTO push_subscriptions(entity_table, entity_id, endpoint, p256dh, auth)
  VALUES (p_table, p_id, p_endpoint, p_p256dh, p_auth)
  ON CONFLICT (endpoint) DO UPDATE SET entity_table=EXCLUDED.entity_table, entity_id=EXCLUDED.entity_id, p256dh=EXCLUDED.p256dh, auth=EXCLUDED.auth;
END;
$function$;

CREATE OR REPLACE FUNCTION public.portal_push_unsubscribe(p_endpoint text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  DELETE FROM push_subscriptions WHERE endpoint = p_endpoint;
END;
$function$;

CREATE OR REPLACE FUNCTION public.staff_push_subscribe(p_endpoint text, p_p256dh text, p_auth text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text;
BEGIN
  v_uid := my_user_id();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authorized'; END IF;
  INSERT INTO push_subscriptions(entity_table, entity_id, endpoint, p256dh, auth)
  VALUES ('users', v_uid, p_endpoint, p_p256dh, p_auth)
  ON CONFLICT (endpoint) DO UPDATE SET entity_table=EXCLUDED.entity_table, entity_id=EXCLUDED.entity_id, p256dh=EXCLUDED.p256dh, auth=EXCLUDED.auth;
END;
$function$;

CREATE OR REPLACE FUNCTION public.staff_push_unsubscribe(p_endpoint text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text;
BEGIN
  v_uid := my_user_id();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authorized'; END IF;
  DELETE FROM push_subscriptions WHERE endpoint = p_endpoint AND entity_table = 'users' AND entity_id = v_uid;
END;
$function$;

CREATE OR REPLACE FUNCTION public.valid_invoice_items(items jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  item jsonb;
  q numeric;
  u numeric;
BEGIN
  IF items IS NULL OR jsonb_typeof(items) <> 'array' THEN
    RETURN true; -- unrecognized shape isn't this constraint's concern
  END IF;
  FOR item IN SELECT * FROM jsonb_array_elements(items) LOOP
    BEGIN
      q := (item->>'qty')::numeric;
      u := (item->>'unit')::numeric;
    EXCEPTION WHEN OTHERS THEN
      CONTINUE; -- non-numeric/missing fields aren't this constraint's concern
    END;
    IF q < 0 OR u < 0 THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION public.verify_engineer_login(p_email text, p_hash text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user    users%ROWTYPE;
  v_token   text;
  v_expires bigint;
  v_result  json;
BEGIN
  SELECT * INTO v_user
  FROM users
  WHERE lower(trim(email)) = lower(trim(p_email))
    AND role = 'engineer'
    AND active = true
  LIMIT 1;

  IF NOT FOUND THEN RETURN NULL; END IF;

  IF v_user.pin IS NULL OR length(v_user.pin) < 64 THEN
    RETURN json_build_object('error','no_hash','name',v_user.name);
  END IF;

  IF left(v_user.pin, 64) != p_hash THEN
    RETURN NULL;
  END IF;

  -- Use md5+random instead of gen_random_bytes to avoid pgcrypto issues
  v_token   := md5(random()::text || clock_timestamp()::text || v_user.id::text);
  v_expires := extract(epoch from now())::bigint + (30 * 24 * 60 * 60);

  UPDATE users
  SET session_token = v_token, session_expires = v_expires,
      last_seen = extract(epoch from now())::bigint
  WHERE id = v_user.id;

  SELECT json_build_object(
    'id', v_user.id, 'name', v_user.name, 'email', v_user.email,
    'phone', v_user.phone, 'role', v_user.role, 'active', true,
    'session_token', v_token, 'session_expires', v_expires,
    'see_landlord', v_user.see_landlord,
    'see_landlord_phone', v_user.see_landlord_phone,
    'see_agent', v_user.see_agent,
    'see_contact', v_user.see_contact,
    'see_price', v_user.see_price
  ) INTO v_result;

  RETURN v_result;
END;
$function$;


-- ============================================================================
-- SECTION 7 — CONSTRAINT ADDED POST-FUNCTION (invoices.items)
-- ============================================================================
-- Deferred from Section 3: valid_invoice_items() must exist before a CHECK
-- constraint can call it. Rejects negative qty/unit values on line items;
-- everything else about invoices.items' shape is enforced by convention
-- only (see docs/architecture/05-database.md §5 for the real element shape).

ALTER TABLE public.invoices
  ADD CONSTRAINT invoices_items_no_negative_values CHECK (valid_invoice_items(items));


-- ============================================================================
-- SECTION 8 — TRIGGERS
-- ============================================================================
-- Exactly one custom trigger exists anywhere in this project (confirmed via
-- pg_trigger, excluding Supabase's own built-in storage/realtime triggers,
-- which every fresh project already has and which this file doesn't need to
-- recreate). It fires on auth.users, not a public-schema table — disaster-
-- recovery path that recreates the primary admin's public.users profile if
-- it's ever missing. Applying this statement requires privileges on the
-- `auth` schema (see the file-level note at the top of this file).

CREATE TRIGGER trg_auto_admin
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.auto_create_admin_profile();


-- ============================================================================
-- SECTION 9 — ROW LEVEL SECURITY: ENABLE + POLICIES
-- ============================================================================
-- RLS is enabled on all 21 tables (confirmed live via pg_class.relrowsecurity
-- — relforcerowsecurity is false everywhere too, i.e. table owners/
-- superusers still bypass RLS as normal). `push_subscriptions` has RLS
-- enabled with ZERO policies, deliberately — see the comment above its
-- ENABLE statement. Every policy below is transcribed verbatim from
-- pg_policies (qual/with_check expressions, roles, cmd) — 41 policies
-- across 20 tables.

ALTER TABLE public.persons ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agencies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agents ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.certs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.job_comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.activity ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.engineer_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.engineer_alerts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cert_reminder_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.overtime ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.portal_contacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_audit ENABLE ROW LEVEL SECURITY;
-- push_subscriptions: RLS enabled, no policies below — by design (Web Push
-- credentials; unreachable via anon/authenticated REST, written only
-- through the SECURITY DEFINER RPCs in Section 6, which run as their
-- owner and so aren't subject to RLS themselves).
ALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;

