-- Delete requires can_delete=true (or admin/manager role) at the database
-- level, not just client-side UI enforcement.
CREATE POLICY jobs_office_delete ON public.jobs FOR DELETE TO authenticated
  USING (is_office() AND EXISTS (
    SELECT 1 FROM users WHERE users.auth_id = (SELECT auth.uid())
      AND (users.can_delete = true OR users.role = ANY (ARRAY['admin'::text,'manager'::text]))
  ));
