-- ============================================================================
-- SECTION 10 — DEFAULT PRIVILEGES / GRANTS
-- ============================================================================
-- Confirmed live via pg_default_acl: this project already has a per-role
-- default-privilege baseline (owner postgres, schema public) that
-- auto-grants ALL on new tables, rwU (SELECT/UPDATE/USAGE) on new
-- sequences, and EXECUTE on new functions, to anon/authenticated/
-- service_role — this is standard Supabase project bootstrapping, present
-- on every fresh project before any migration ever runs, which is exactly
-- why almost none of the 41 functions above needed an explicit GRANT
-- statement to be callable by anon/authenticated. The block below makes
-- that assumption explicit and self-sufficient rather than silently relying
-- on it, then the REVOKEs beneath it narrow the ~15 functions whose live
-- grants are less permissive than that default.

GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL FUNCTIONS IN SCHEMA public TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON SEQUENCES TO anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO anon, authenticated, service_role;

-- Four functions have NO anon/authenticated EXECUTE grant live — postgres/
-- service_role (migrations, Edge Functions using the service key) only.
-- admin_set_seq: raw sequence-position surgery, dangerous if public.
-- auto_create_admin_profile: trigger function only, never meant to be
--   called directly. create_confirmed_user: creates a real auth.users row
--   bypassing normal signup — admin/service-role tooling only.
-- verify_engineer_login: dead — references a `pin` column dropped from
--   `users` (superseded by pin_hash); revoked live by
--   20260725163831_h1_revoke_dead_verify_engineer_login_rpc.sql; kept here
--   verbatim per this file's own header note, not re-enabled.
REVOKE ALL ON FUNCTION public.admin_set_seq(text, integer) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.auto_create_admin_profile() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.create_confirmed_user(text, text) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.verify_engineer_login(text, text) FROM PUBLIC, anon, authenticated;

-- Eleven functions are authenticated-only live (office-side utilities and
-- admin actions that anon — an unauthenticated Portal/public visitor —
-- should never be able to invoke, even though the schema default would
-- otherwise grant it EXECUTE too).
REVOKE EXECUTE ON FUNCTION public.check_cert_reminder_setup() FROM anon;
REVOKE EXECUTE ON FUNCTION public.engineer_allow_pin_reset(text, boolean) FROM anon;
REVOKE EXECUTE ON FUNCTION public.engineer_pin_clear(text, boolean) FROM anon;
REVOKE EXECUTE ON FUNCTION public.engineer_pin_set(text, text) FROM anon;
REVOKE EXECUTE ON FUNCTION public.get_auth_users() FROM anon;
REVOKE EXECUTE ON FUNCTION public.next_agn_num() FROM anon;
REVOKE EXECUTE ON FUNCTION public.next_cr_num() FROM anon;
REVOKE EXECUTE ON FUNCTION public.next_inv_num() FROM anon;
REVOKE EXECUTE ON FUNCTION public.next_job_num() FROM anon;
REVOKE EXECUTE ON FUNCTION public.next_proforma_num() FROM anon;
REVOKE EXECUTE ON FUNCTION public.portal_pin_reset(text, text) FROM anon;

-- The remaining 26 functions (engineer_pin_login, engineer_pin_self_setup,
-- engineer_session_logout, is_engineer, is_office, is_valid_engineer_token,
-- my_engineer_name, my_token_engineer_name, my_user_id, portal_get_agency,
-- portal_get_agency_agents, portal_get_attachments, portal_get_certs,
-- portal_get_invoices, portal_get_jobs, portal_get_person,
-- portal_get_requests, portal_next_request_ref, portal_pin_set,
-- portal_pin_status, portal_pin_verify, portal_push_subscribe,
-- portal_push_unsubscribe, staff_push_subscribe, staff_push_unsubscribe,
-- valid_invoice_items) keep the schema default: EXECUTE for both anon and
-- authenticated. No further action needed for those.


